+
+    public void testResponseLiteral() throws IOException {
+        String responseLiteral = """
+            {
+                "object": "list",
+                "model": "model",
+                "data": [
+                    {
+                        "index": 2,
+                        "relevance_score": 0.98005307
+                    },
