+import org.elasticsearch.logsdb.datageneration.FieldType;
+
+import java.util.List;
+import java.util.Map;
+import java.util.Objects;
+
+public class BooleanFieldBlockLoaderTests extends BlockLoaderTestCase {
+    public BooleanFieldBlockLoaderTests() {
+        super(FieldType.BOOLEAN);
+    }
+
+    @Override
+    @SuppressWarnings("unchecked")
+    protected Object expected(Map<String, Object> fieldMapping, Object value, boolean syntheticSource) {
+        var rawNullValue = fieldMapping.get("null_value");
+
+        Boolean nullValue;
+        if (rawNullValue == null) {
+            nullValue = null;
+        } else if (rawNullValue instanceof Boolean b) {
+            nullValue = b;
+        } else if (rawNullValue instanceof String s) {
+            nullValue = Boolean.parseBoolean(s);
+        } else {
+            throw new IllegalStateException("Unexpected null_value format");
+        }
+
+        if (value instanceof List<?> == false) {
+            return convert(value, nullValue);
+        }
+
+        if ((boolean) fieldMapping.getOrDefault("doc_values", false)) {
+            // Sorted
+            var resultList = ((List<Object>) value).stream().map(v -> convert(v, nullValue)).filter(Objects::nonNull).sorted().toList();
+            return maybeFoldList(resultList);
+        }
+
+        // parsing from source, not sorted
+        var resultList = ((List<Object>) value).stream().map(v -> convert(v, nullValue)).filter(Objects::nonNull).toList();
+        return maybeFoldList(resultList);
+    }
+
+    @SuppressWarnings("unchecked")
+    private Object convert(Object value, Object nullValue) {
+        if (value == null) {
+            return nullValue;
+        }
+        if (value instanceof String s) {
+            if (s.isEmpty()) {
+                // This is a documented behavior.
+                return false;
+            }
+            if (value.equals("true")) {
+                return true;
+            }
+            if (value.equals("false")) {
+                return false;
